	description := ""

	// Extract title
	titleStart := indexOf(content, "<title>")
	titleEnd := indexOf(content, "</title>")
	if titleStart != -1 && titleEnd != -1 && titleEnd > titleStart {
		title = content[titleStart+7 : titleEnd]
	}

