	"golang.org/x/net/html"
)

// RequestBody represents the expected JSON request body
type RequestBody struct {
	URL string `json:"url"`
}

// PreviewResponse represents the JSON response containing page preview data
type PreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	URL         string `json:"url"`
}

// ErrorResponse represents an error response
type ErrorResponse struct {
	Error string `json:"error"`
}

// FetchURLPreview handles POST /preview requests
// It fetches the provided URL, parses HTML to extract title and meta description
func FetchURLPreview(ctx echo.Context) error {
	// Parse request body
	var reqBody RequestBody
	if err := ctx.Bind(&reqBody); err != nil {
		return ctx.JSON(http.StatusBadRequest, ErrorResponse{
			Error: "Invalid request body: " + err.Error(),
		})
	}

	// Validate URL is provided
	if strings.TrimSpace(reqBody.URL) == "" {
		return ctx.JSON(http.StatusBadRequest, ErrorResponse{
			Error: "URL field is required",
		})
	}

	// Create HTTP client with 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Create context with timeout for fetch operation
	ctxTimeout, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	// Create HTTP request
	req, err := http.NewRequestWithContext(ctxTimeout, http.MethodGet, reqBody.URL, nil)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, ErrorResponse{
			Error: fmt.Sprintf("Failed to create request: %v", err),
		})
	}

	// Set headers to mimic a browser request
	req.Header.Set("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36")
	req.Header.Set("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8")
	req.Header.Set("Accept-Language", "en-US,en;q=0.5")

	// Execute the request
	resp, err := client.Do(req)
	if err != nil {
		return ctx.JSON(http.StatusBadGateway, ErrorResponse{
			Error: fmt.Sprintf("Failed to fetch URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if response status is OK
	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusBadGateway, ErrorResponse{
			Error: fmt.Sprintf("URL returned status %d", resp.StatusCode),
		})
	}

	// Limit reading body to prevent memory issues (10MB limit)
	limitedReader := io.LimitReader(resp.Body, 10*1024*1024)
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, ErrorResponse{
			Error: fmt.Sprintf("Failed to read response body: %v", err),
		})
	}

	// Parse HTML and extract title and meta description
	title, description := parseHTML(string(body))

	// Return the preview response
	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
		URL:         reqBody.URL,
	})
}

// parseHTML extracts the title and meta description from HTML content
func parseHTML(htmlContent string) (title string, description string) {
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return "", ""
	}

	// Traverse the HTML tree to find title and meta description
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "title":
				if n.FirstChild != nil {
					title = n.FirstChild.Data
				}
			case "meta":
				var name, content string
				for _, attr := range n.Attr {
					switch attr.Key {
					case "name":
						name = strings.ToLower(attr.Val)
					case "content":
						content = attr.Val
					}
				}
				if name == "description" && description == "" {
					description = content
				}
			}
		}

		// Continue traversing children
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)

	return title, description
}

func main() {
	e := echo.New()

	// Register the handler under /preview path
	e.POST("/preview", FetchURLPreview)

	// Start server on port 8080
	e.Logger.Fatal(e.Start(":8080"))
}

