// RequestPayload represents the incoming JSON request body.
type RequestPayload struct {
	URL string `json:"url"`
}

// PreviewResponse represents the JSON response containing the page preview.
type PreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	URL         string `json:"url"`
}

// FetchURLPreview handles POST /preview requests.
// It fetches the provided URL, parses the HTML to extract the title and meta description,
// and returns the result as JSON.
func FetchURLPreview(ctx echo.Context) error {
	// Parse the request body
	var payload RequestPayload
	if err := json.NewDecoder(ctx.Request().Body).Decode(&payload); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{
			"error": "Invalid JSON body",
		})
	}

	if payload.URL == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{
			"error": "URL field is required",
		})
	}

	// Create HTTP client with 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Fetch the URL
	resp, err := client.Get(payload.URL)
	if err != nil {
		return ctx.JSON(http.StatusBadGateway, map[string]string{
			"error": "Failed to fetch URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Read the response body
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{
			"error": "Failed to read response body",
		})
	}

	// Parse HTML to extract title and meta description
	title, description := parseHTML(string(body))

	// Return the result as JSON
	response := PreviewResponse{
		Title:       title,
		Description: description,
		URL:         payload.URL,
	}
	return ctx.JSON(http.StatusOK, response)
}

// parseHTML parses the HTML string and extracts the title and meta description.
func parseHTML(htmlContent string) (title string, description string) {
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return "", ""
	}

	var extract func(*html.Node)
	extract = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" && n.FirstChild != nil {
				title = strings.TrimSpace(n.FirstChild.Data)
			}
			if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = strings.ToLower(attr.Val)
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" && description == "" {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			extract(c)
		}
	}
	extract(doc)
	return title, description
}

func main() {
	e := echo.New()

	// Register the handler under the /preview path
	e.POST("/preview", FetchURLPreview)

	// Start the server on port 8080
	e.Logger.Fatal(e.Start(":8080"))
}

