// FetchURLPreview handles POST /preview requests
func FetchURLPreview(ctx echo.Context) error {
	// Parse request body
	var reqBody RequestBody
	if err := json.NewDecoder(ctx.Request().Body).Decode(&reqBody); err != nil {
		return ctx.JSON(http.StatusBadRequest, ErrorResponse{
			Error: "Invalid JSON body: " + err.Error(),
		})
	}

	// Validate URL
	if reqBody.URL == "" {
		return ctx.JSON(http.StatusBadRequest, ErrorResponse{
			Error: "URL field is required",
		})
	}

	// Create HTTP client with 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Create context with timeout for the request
	reqCtx, cancel := context.WithTimeout(ctx.Request().Context(), 3*time.Second)
	defer cancel()

	// Create HTTP request
	req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, reqBody.URL, nil)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, ErrorResponse{
			Error: "Invalid URL: " + err.Error(),
		})
	}

	// Set User-Agent to avoid being blocked by some servers
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; FetchURLPreview/1.0)")

	// Execute the request
	resp, err := client.Do(req)
	if err != nil {
		return ctx.JSON(http.StatusBadGateway, ErrorResponse{
			Error: fmt.Sprintf("Failed to fetch URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check response status code
	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusBadGateway, ErrorResponse{
			Error: fmt.Sprintf("URL returned status %d", resp.StatusCode),
		})
	}

	// Limit reading body to 10MB to prevent memory issues
	limitedReader := io.LimitReader(resp.Body, 10*1024*1024)

	// Parse HTML
	doc, err := html.Parse(limitedReader)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, ErrorResponse{
			Error: "Failed to parse HTML: " + err.Error(),
		})
	}

	// Extract title and meta description
	title, description := extractMetaData(doc)

	// Return the preview response
	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
		URL:         reqBody.URL,
	})
}

// extractMetaData traverses the HTML tree to find the title and meta description
func extractMetaData(n *html.Node) (title string, description string) {
	if n.Type == html.ElementNode {
		if n.Data == "title" && n.FirstChild != nil {
			title = strings.TrimSpace(n.FirstChild.Data)
		}
		if n.Data == "meta" {
			var name, content string
			for _, attr := range n.Attr {
				if attr.Key == "name" {
					name = strings.ToLower(attr.Val)
				}
				if attr.Key == "content" {
					content = attr.Val
				}
			}
			if name == "description" {
				description = content
			}
		}
	}

	// Recursively traverse child nodes
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		t, d := extractMetaData(c)
		if title == "" && t != "" {
			title = t
		}
		if description == "" && d != "" {
			description = d
		}
	}

	return title, description
}

func main() {
	e := echo.New()

	// Register the handler
	e.POST("/preview", FetchURLPreview)

	// Start server
	e.Logger.Fatal(e.Start(":8080"))
}

