// RequestBody represents the expected JSON request body
type RequestBody struct {
	URL string `json:"url"`
}

// PreviewResult represents the JSON response with extracted data
type PreviewResult struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	URL         string `json:"url"`
}

// ErrorResponse represents an error response
type ErrorResponse struct {
	Error string `json:"error"`
}

// FetchURLPreview handles POST /preview requests
func FetchURLPreview(ctx echo.Context) error {
	// Parse request body
	var reqBody RequestBody
	if err := json.NewDecoder(ctx.Request().Body).Decode(&reqBody); err != nil {
		return ctx.JSON(http.StatusBadRequest, ErrorResponse{
			Error: "Invalid JSON body",
		})
	}

	// Validate URL
	if strings.TrimSpace(reqBody.URL) == "" {
		return ctx.JSON(http.StatusBadRequest, ErrorResponse{
			Error: "URL field is required",
		})
	}

	// Create HTTP client with 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Create context with timeout
	ctxTimeout, cancel := context.WithTimeout(ctx.Request().Context(), 3*time.Second)
	defer cancel()

	// Create request with context
	req, err := http.NewRequestWithContext(ctxTimeout, http.MethodGet, reqBody.URL, nil)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, ErrorResponse{
			Error: "Failed to create request",
		})
	}

	// Execute request
	resp, err := client.Do(req)
	if err != nil {
		return ctx.JSON(http.StatusBadGateway, ErrorResponse{
			Error: "Failed to fetch URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Read response body
	body, err := io.ReadAll(io.LimitReader(resp.Body, 10*1024*1024)) // Limit to 10MB
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, ErrorResponse{
			Error: "Failed to read response body",
		})
	}

	// Parse HTML and extract title and meta description
	title, description := extractHTMLMeta(string(body))

	// Return result
	result := PreviewResult{
		Title:       title,
		Description: description,
		URL:         reqBody.URL,
	}

	return ctx.JSON(http.StatusOK, result)
}

// extractHTMLMeta parses HTML content and extracts title and meta description
func extractHTMLMeta(htmlContent string) (title string, description string) {
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return "", ""
	}

	var extract func(*html.Node)
	extract = func(n *html.Node) {
		if n.Type == html.ElementNode {
			// Extract title
			if n.Data == "title" && n.FirstChild != nil {
				title = strings.TrimSpace(n.FirstChild.Data)
			}

			// Extract meta description
			if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = strings.ToLower(attr.Val)
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" && content != "" {
					description = content
				}
			}
		}

		// Recursively process child nodes
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			extract(c)
		}
	}

	extract(doc)
	return title, description
}

func main() {
	e := echo.New()

	// Register the handler under /preview path
	e.POST("/preview", FetchURLPreview)

	// Start server
	e.Logger.Fatal(e.Start(":8080"))
}

